def solve(xs: list[int]) -> int:
    if not xs:
        return 0
    if all(x == xs[0] for x in xs):
        return sum(xs)
    s = sum(xs)
    has_odd = any(x % 2 != 0 for x in xs)
    if has_odd:
        return s if s % 2 == 0 else s + 1
    else:
        return s if s % 2 == 1 else s + 1

def solve(xs: list[int]) -> int:
    total = 0
    sign = 1
    for x in xs:
        if x % 3 == 0:
            continue
        total += sign * x
        sign = -sign
    return total
